def add_spells(level, spells_to_add):
    """Add spells to DB, avoiding duplicates."""
    existing_names = {spell.name for spell in session.query(Spell.name).all()}
    new_spells = [spell for spell in spells_to_add if spell.name not in existing_names]
    
    if new_spells:
        session.add_all(new_spells)
        session.commit()
        print(f"[SUCCESS] Added {len(new_spells)} {level} spells")
        print(f"✅ Properties format: Simple keywords only")
        print(f"✅ Property data stored in property_data JSON field")
        print(f"✅ Skill modifiers structured for frontend display")
        print(f"✅ Attunement requirements properly flagged")
    else:
        print("[INFO] All spells already exist.")

def add_all():
    add_spells("Cantrip", cantrips)
    add_spells("Cantrip", forgot_some)
    add_spells("1st Level", lvl1)
    add_spells("2nd Level", lvl2)
    add_spells("3rd Level", lvl3)
    add_spells("4th Level", lvl4)
    add_spells("5th Level", lvl5)
    add_spells("6th Level", lvl6)
    add_spells("7th Level", lvl7)
    add_spells("8th Level", lvl8)
    add_spells("9th Level", lvl9)
